import json, sys

def brief(v, n=200):
    s = json.dumps(v) if not isinstance(v, str) else v
    s = s.replace("\n", " \\n ")
    return s[:n] + ("..." if len(s) > n else "")

def walk(obj, path=""):
    pass

path = sys.argv[1]
maxlines = int(sys.argv[2]) if len(sys.argv) > 2 else 10**9
with open(path) as f:
    for i, line in enumerate(f):
        if i >= maxlines:
            break
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception as e:
            print(f"[{i}] PARSE ERROR: {e}")
            continue
        ts = obj.get("timestamp") or obj.get("ts") or ""
        typ = obj.get("type") or ""
        role = None
        text_bits = []
        msg = obj.get("message")
        if isinstance(msg, dict):
            role = msg.get("role")
            content = msg.get("content")
            if isinstance(content, str):
                text_bits.append(brief(content, 300))
            elif isinstance(content, list):
                for c in content:
                    if not isinstance(c, dict):
                        continue
                    ctype = c.get("type")
                    if ctype == "text":
                        text_bits.append("TEXT: " + brief(c.get("text",""), 300))
                    elif ctype == "tool_use":
                        text_bits.append(f"TOOL_USE {c.get('name')}: " + brief(c.get("input", {}), 200))
                    elif ctype == "tool_result":
                        cont = c.get("content")
                        text_bits.append("TOOL_RESULT: " + brief(cont, 150))
                    else:
                        text_bits.append(f"[{ctype}]")
        print(f"[{i}] {ts} type={typ} role={role} :: " + " | ".join(text_bits))

