// Screenshot driver for hosts the browser cannot tunnel to: every request is
// fetched with curl (which the agent proxy allows) and fulfilled into the page.
// usage: node shot-via-curl.mjs <url> <outPath> [waitMs] [width] [height] [fullPage]
import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';
import { execFile } from 'node:child_process';
import { readFile, mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const [url, outPath, waitMs = '6000', width = '1280', height = '900', fullPage = ''] = process.argv.slice(2);
if (!url || !outPath) { console.error('usage: node shot-via-curl.mjs <url> <out> [waitMs] [w] [h] [full]'); process.exit(2); }

const tmp = await mkdtemp(join(tmpdir(), 'shot-'));
let n = 0;
const cache = new Map();

function curlFetch(req) {
  const u = req.url();
  const key = req.method() + ' ' + u;
  if (req.method() === 'GET' && cache.has(key)) return cache.get(key);
  const p = new Promise((resolve) => {
    const id = n++;
    const bodyFile = join(tmp, `b${id}`), hdrFile = join(tmp, `h${id}`);
    const args = ['-sS', '-L', '-m', '25', '--compressed', '-o', bodyFile, '-D', hdrFile,
      '-X', req.method(), '-H', 'User-Agent: Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/128 Safari/537.36',
      '-H', 'Accept: */*'];
    const post = req.postDataBuffer();
    if (post) { args.push('--data-binary', '@-'); }
    const ct = req.headers()['content-type'];
    if (ct) args.push('-H', `Content-Type: ${ct}`);
    args.push(u);
    const child = execFile('curl', args, { maxBuffer: 64e6 }, async (err) => {
      if (err) return resolve(null);
      try {
        const hdrs = (await readFile(hdrFile, 'utf8')).split(/\r?\n\r?\n/).filter(Boolean);
        const last = hdrs[hdrs.length - 1] || '';
        const status = Number(last.match(/^HTTP\/[\d.]+ (\d+)/)?.[1] || 200);
        const contentType = last.match(/^content-type:\s*(.+)$/im)?.[1]?.trim() || 'application/octet-stream';
        const body = await readFile(bodyFile);
        resolve({ status, contentType, body });
      } catch { resolve(null); }
    });
    if (post) { child.stdin.end(post); }
  });
  if (req.method() === 'GET') cache.set(key, p);
  return p;
}

const browser = await chromium.launch();
try {
  const ctx = await browser.newContext({ viewport: { width: +width, height: +height }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  await page.route('**/*', async (route) => {
    const req = route.request();
    if (!/^https?:/.test(req.url())) return route.abort();
    const res = await curlFetch(req);
    if (!res) return route.abort();
    await route.fulfill({ status: res.status, contentType: res.contentType, body: res.body });
  });
  await page.goto(url, { waitUntil: 'load', timeout: 90000 }).catch((e) => console.log(`goto note: ${e.message.split('\n')[0]}`));
  await page.waitForTimeout(+waitMs);
  await page.screenshot({ path: outPath, fullPage: fullPage === 'full' });
  console.log(`saved ${outPath} (${n} requests)`);
} finally {
  await browser.close();
  await rm(tmp, { recursive: true, force: true });
}
